@router.post("/media/assets/{asset_id}/labels")
async def add_asset_labels(
    asset_id: PydanticObjectId,
    payload: MediaLabelsPayload,
    current_user: User = Depends(get_current_user)
):
    asset = await MediaAssetDocument.get(asset_id)
    if not asset:
        raise HTTPException(status_code=404, detail="Media asset not found")

    if asset.creator_user_id != current_user.id and current_user.role != "CONTENT_ADMIN":
        raise HTTPException(status_code=403, detail="Forbidden: unauthorized to edit asset labels")

    await asset.update(
        Set({MediaAssetDocument.curated_labels: payload.labels})
    )
    return {"status": "labels_updated", "asset_id": str(asset.id)}
